<script setup>import{onMounted,ref}from'vue';import{supabase}from'../supabase.js';import{useContract}from'../composables/useContract.js';import BottomNav from'../components/BottomNav.vue';const{contract,user,load}=useContract(),docs=ref([]),name=ref(''),file=ref(null),message=ref('');async function init(){if(!(await load()))return;const{data}=await supabase.from('car_documents').select('*').eq('contract_id',contract.value.id).order('created_at',{ascending:false});docs.value=data||[]}async function add(){if(!name.value||!file.value)return message.value='กรอกชื่อและเลือกไฟล์';const path=`${contract.value.id}/${user.value.id}/${crypto.randomUUID()}-${file.value.name}`;const u=await supabase.storage.from('car-documents').upload(path,file.value);if(u.error)return message.value=u.error.message;const q=await supabase.from('car_documents').insert({contract_id:contract.value.id,uploaded_by:user.value.id,name:name.value,file_path:path});if(q.error)return message.value=q.error.message;name.value='';file.value=null;message.value='เพิ่มเอกสารแล้ว';await init()}onMounted(init)</script><template><main class="app-shell"><header class="page-head"><RouterLink to="/dashboard">‹</RouterLink><h1>เอกสารรถ</h1></header><div v-if="message" class="alert">{{message}}</div><section class="card"><h3>เพิ่มเอกสาร</h3><input v-model="name" placeholder="ชื่อเอกสาร"><input type="file" @change="file=$event.target.files?.[0]||null"><button class="btn primary full" @click="add">เพิ่มเอกสาร</button></section><section class="card"><h3>รายการเอกสาร</h3><div v-for="d in docs" :key="d.id" class="status-row"><span>▱</span><div><b>{{d.name}}</b><small>{{new Date(d.created_at).toLocaleString('th-TH')}}</small></div></div><div v-if="!docs.length" class="state">ยังไม่มีเอกสาร</div></section><BottomNav/></main></template>
